def drop_evens(nums):
    for n in nums:
        if n % 2 == 0:
            nums.remove(n)
    return nums

print(drop_evens([1, 2, 2, 3]))

def tally(words):
    counts = {}
    for w in words:
        counts[w] += 1
    return counts

def render_log(lines):
    page = ""
    for line in lines:
        page += line + "\n"
    return page
